"""Randomized differential test of the pattern engine vs Python re."""
import random, re, sys
sys.path.insert(0, '/workspace/project/src')
import eywa.regex as R

def rand_ast(depth):
    r = random.random()
    if depth > 3:
        r = min(r, 0.45)
    if r < 0.25:
        return ('lit', random.choice("abc-*()[]|\\x."))
    if r < 0.35:
        return ('empty',)
    if r < 0.55:
        n = random.randint(1, 3)
        items = []
        for _ in range(n):
            if random.random() < 0.5:
                lo = random.choice("a-cx")
                hi = random.choice("bdy0")
                if ord(lo) > ord(hi):
                    lo, hi = hi, lo
                items.append(('range', lo, hi))
            else:
                items.append(('lit', random.choice("ab]\\-[")))
        return ('class', items)
    if r < 0.75:
        return ('seq', [rand_ast(depth + 1) for _ in range(random.randint(0, 3))])
    if r < 0.9:
        return ('alt', [rand_ast(depth + 1) for _ in range(random.randint(0, 3))])
    return ('star', rand_ast(depth + 1))

def esc_out(c):
    return "\\" + c if c in "\\()[]|*" else c

def esc_in(c):
    return "\\" + c if c in "\\]-" else c

def to_text(ast):
    k = ast[0]
    if k == 'lit':
        return esc_out(ast[1])
    if k == 'empty':
        return ""
    if k == 'class':
        parts = []
        for item in ast[1]:
            if item[0] == 'lit':
                parts.append(esc_in(item[1]))
            else:
                parts.append(esc_in(item[1]) + "-" + esc_in(item[2]))
        return "[" + "".join(parts) + "]"
    if k == 'seq':
        return "(" + "".join(to_text(a) for a in ast[1]) + ")"
    if k == 'alt':
        return "(" + "|".join(to_text(a) for a in ast[1]) + ")"
    if k == 'star':
        return "(" + to_text(ast[1]) + ")*"
    raise AssertionError

def to_py(ast):
    k = ast[0]
    if k == 'lit':
        return re.escape(ast[1])
    if k == 'empty':
        return ""
    if k == 'class':
        parts = []
        for item in ast[1]:
            if item[0] == 'lit':
                parts.append(re.escape(item[1]))
            else:
                parts.append(re.escape(item[1]) + "-" + re.escape(item[2]))
        return "[" + "".join(parts) + "]"
    if k == 'seq':
        return "(" + "".join(to_py(a) for a in ast[1]) + ")"
    if k == 'alt':
        return "(" + "|".join(to_py(a) for a in ast[1]) + ")"
    if k == 'star':
        return "(" + to_py(ast[1]) + ")*"
    raise AssertionError

random.seed(99)
checked = 0
for trial in range(5000):
    ast = rand_ast(0)
    text = to_text(ast)
    try:
        node = R.parse_pattern(text)
    except Exception as e:
        print("PARSE ERR", repr(text), e)
        sys.exit(1)
    cre = re.compile(to_py(ast))
    pat = R.Pattern(node)
    s = "".join(random.choice("abc-*()[]|\\x.") for _ in range(random.randint(0, 6)))
    a = pat.match(s)
    b = cre.fullmatch(s) is not None
    if a != b:
        print("MISMATCH", repr(text), repr(s), a, b)
        sys.exit(1)
    checked += 1
print("T11 OK", checked, "cases")
EOF
